if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[24707] = { id = 24707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ballad of Maximillian", description = "The time we have waited for is upon us, Squire {name}.  Un'Goro's brood mother will perish at my hands.  The gravity of our task weighs heavily on me, but with the power of the Light behind us, we are guaranteed to succeed.\n\nAre you ready to depart?", completion = "The day is saved!  Huzzah!  Today we learned that while armor can be replaced, valor has no price.\n\nBecause of your key involvement in this task, I hereby graduate you from squire to fledgling knight.  No longer do the chains of servitude bind you to me; you are free to serve other masters.\n\nGo with honor, young hero!  For chivalry, the Light, and the beauty of Doloria!", objectives = "Help Maximillian of Northshire kill the Devilsaur Queen. If you become separated from Maximillian, meet him at Golakka Hot Springs in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24708] = { id = 24708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fossil-Finder 3000", description = "One of the things I hate the most about digging is the fact that half the time, all you find is dirt.  That's why I've been spending most of my time out here tinkering instead of digging.\n\nLet me show you what I've invented: the Fossil-Finder 3000.  I just put the finishing touches on it.  If it works properly, it should find the largest fossils in the area.  I know, sweet, huh?\n\nTest it out and see if you can find some ridiculously big dinosaur bones.", progress = "Have you found anything?  Did it work?", completion = "What an interesting femur you've brought here, but why's it all sharp and curvy?\n\n...\n\nWait a minute, that thing's a TALON?  A dinosaur with a talon that size would've been... well, really big, that's for sure.  Is this the only fossil that you found there?", objectives = "Obtain an Enormous Dinosaur Talon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24709] = { id = 24709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Two Shovels", description = "Hey wait a minute, this bone has pickax marks on it.  These aren't yours, are they?  No, I recognize this mark... this must be that blasted dwarf!  Gah!\n\nLet me step back for a minute and explain.  There's another archaeologist south of here named Durrin Direshovel.  He practices a reckless, devil-may-care brand of archaeology that offends even me.\n\nA priceless fossil, ruined by sloppy pick-work.  This is the last straw, Durrin!\n\n{name}, go put an end to Direshovel and his negligent excavation.", progress = "Is the deed done?  Did you manage to salvage his notes?", completion = "I knew it!  Durrin HAS been digging around here.  And he's been excavating what could be the archaeological find of the century!  Now I just have to find out where he's stashing the bones...\n\nThanks {name}.  You've been a great help.", objectives = "Kill Durrin Direshovel and obtain Durrin's Archaeological Findings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nHe will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", completion = "Such a senseless waste! Arthas goes too far!\n\nI can only hope what we find in the Halls of Reflection makes this somehow worth it.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", objectives = "Kill Scourgelord Tyrannus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "We must press on, hero. We've come so far... we're so close to our goal.\n\nI must delay a moment to send Elandra back to the airship. I'm uncertain how we're going to escape with so many men lost and so few to keep our path in secure.\n\nContinue on. I will meet you in the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready. Arthas may not be here, but it would be naive to think that he would leave Frostmourne unguarded entirely.", objectives = "Meet Lady Jaina Proudmoore at the entrance to the Halls of Reflection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nThere, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", completion = "The Halls of Reflection lie ahead.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", objectives = "Kill Scourgelord Tyrannus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "Keep moving, the sword is close.\n\nI need a moment to send one of my dark rangers back to the airship. With all of our fodder gone, I will not be caught unprepared - we will need any help they can send.\n\nGo. I will meet you in the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready, {class}. I will not be so naive as to think that Arthas left his precious sword entirely unguarded.", objectives = "Meet Lady Sylvanas Windrunner inside the entrance to the Halls of Reflection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24714] = { id = 24714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions.  You've seen mechanical squirrels, yes?  Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has been studying the local wildlife at Fungal Rock for several months, but she should have returned by now.  I fear the worst for her.\n\nCan you help me find her?", completion = "A-Me lies motionless before you.  No power seems to be running through her components.", objectives = "Find A-Me 01 at Fungal Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24715] = { id = 24715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing A-Me 01", description = "<Suddenly, the robotic gorilla's eyes light up, and it begins to speak.>\n\n\"...operational capacity... less than 5%... accidentally... punctured oil reservoir...\"\n\n\"...use coconut milk... rock... save A-Me 01...\"\n\n<A-Me closes her eyes.>", progress = "<A-Me 01 has gone into power save mode.>", completion = "You pour the coconut milk into what appears to be A-Me 01's oil reservoir.  You hear the sound of gears whirring and actuators firing.", objectives = "You're pretty sure that A-Me 01 has asked you to obtain an Un'Goro Coconut, crack it on the rock nearby, and give her the High Viscosity Coconut Milk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24716] = { id = 24716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning A-Me 01", description = "Greetings.  I unit A-Me 01.  You... {race}?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data and now will bring to Karna.\n\nIt time for A-Me to return to Karna.  You come with?  We embark right away, so make sure you ready first.", objectives = "Escort A-Me 01 back to Karna Remtravel at Mossy Pile.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24717] = { id = 24717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apes of Un'Goro", description = "There's plenty of money to be had here in Un'Goro, you just need to know where to look!\n\nApes may be common here in Un'Goro, but they're much rarer up north.  In Everlook, a gorilla hide fetches ten times what you'll get for it down here!\n\nI'm not going to send you all the way up to Winterspring - that'd be irresponsible - but I could use your help actually obtaining some hides.\n\nYou'll find gorillas at Fungal Rock, to the northeast, near a waterfall.  Don't forget to check inside the cave!", progress = "I never know what style is in vogue, so I'll want a few different colors.  Try to get hides from each different type of gorilla there.", completion = "Wow, 2 of each color!  You're certainly an overachiever, {name}.  My companions and I could use a {race} like you around here.  Ever consider a career in profiteering?", objectives = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Gremix at Mossy Pile.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24718] = { id = 24718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mighty U'cha", description = "Looking around, you see bits of red fur laying around this part of the cave.  It appears to match the consistency of gorilla fur.\n\nBased on your conversations with Gremix, you know that he would almost certainly be interested in a red gorilla hide, if you were to obtain one.", progress = "Red fur?  What're you waiting for!  Go back and get that red gorilla!  I'll pay you double!", completion = "Wow, look at this one!  Not just the color, but the size of it... you could cover a tauren with this.\n\nHere you go, {name}.  You've earned this.  Stick around, I'm sure we can find something else for you to do.", objectives = "Bring U'cha's Pelt to Gremix at Mossy Pile.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24719] = { id = 24719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws of White", description = "Stop, {race}.  I could use the help of a {class} like you.\n\nRight outside this camp, there are raptors with deadly claws.  I've been using the claws for druid rituals, but it doesn't seem to be working.  However, I did notice that some of those raptors sometimes have white claws, when most have deathly black ones.\n\nThe earth works in strange ways.  Maybe you could fetch me some of the white claws, and I'll try one last time?", progress = "Have you gotten any of the claws yet?", completion = "My mentor says that sometimes you have to take away from nature before you can give back.  These raptors... I feel that they died for good cause.\n\nThank you, {name}.", objectives = "Obtain 5 White Ravasaur Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24720] = { id = 24720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals of Power", description = "I'm sure you've noticed 'em, {name}. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?  \n\nYou'll find yellow crystals to the northwest, red crystals to the... oh, I'm sure you'll figure it out.", progress = "I just know I'm onto something here, {name}!", completion = "Now I will continue my experiments! Thank you, {name}.", objectives = "Collect 7 Power Crystals of each color: red, blue, yellow, and green.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24721] = { id = 24721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Pylon", description = "High up in the cliffs above me there is a large crystal pylon.  Who placed it there, I cannot say, nor can I determine any reason that it would be built in such a strange place.\n\nMaybe you can make more of it than I can.  I personally don't care what it does, so you needn't report back to me, but perhaps one of the scholars in Marshal's Stand might be interested in what you discover.", completion = "You were right to bring this pylon to my attention, {name}.  This is just the sort of thing I've been studying.", objectives = "Touch the Eastern Crystal Pylon in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24722] = { id = 24722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Pylon", description = "You've done us a number of favors, {name}... now let Gremix do one for you.  The attacks on Marshal's Refuge were terrible, undoubtedly.  They came without warning, and took no prisoners.  They were lucky that so many of them survived.\n\nA few weeks ago, I came across a crystal pylon in the cliffs to the northeast of here, east of Marshal's Refuge.  I think the pylon and the attacks may be related somehow.  Maybe you can investigate?  I'm sure someone in Marshal's Stand will thank you.", completion = "You think this may be related to the attacks on Marshal's Refuge, {name}?", objectives = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24723] = { id = 24723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Pylon", description = "Durrin's research touched on one area that intrigues me: a potential link between the titans and the dinosaurs.  J.D. Collie back at camp is always talking about titan this and crystal that... maybe she'd be interested.\n\nBefore you report to her, you might want to check out the crystal pylon not far from here.  It's just up in the cliffs, to the west of here.  It's got crystals on it, and it always seemed to me like it might have something to do with the titans.", completion = "A pylon in the west?  And a relationship between titans and dinosaurs?  This is a lot to take in, {name}.", objectives = "Discover the location of the Western Crystal Pylon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24724] = { id = 24724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Restore", progress = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24725] = { id = 24725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Charge", progress = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24726] = { id = 24726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Force", progress = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24727] = { id = 24727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Spire", progress = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24728] = { id = 24728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Ward", progress = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24729] = { id = 24729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Yield", progress = "The Pylon table allows you to combine red power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to weaken an enemy's defenses.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24730] = { id = 24730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me, in case anyone's listening...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!", objectives = "Obtain 8 Dinosaur Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24731] = { id = 24731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nStart your search to the west.", progress = "Do not take my words lightly, {name}. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, {name}. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh.", objectives = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24732] = { id = 24732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, {name}. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", progress = "Be careful, {name}. Getting close to any nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, {name}. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.", objectives = "Obtain 2 Ravasaur Pheromone Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24733] = { id = 24733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan.  Continue following the river to the north, and look for a bend in the river.  It was here I saw Lar'korwi last.  You will know you are in the right area because of all the bones from massive creatures that once wandered nearby.\n\nTake the meat you recovered and place it there.  Then, rub this mixture I created on the meat.\n\nIf both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", progress = "Do not let fear overpower you, {name}. Fear is the great betrayer... you must remain strong!", completion = "The Earth Mother be praised! You've done it! Fair play to you, {name}. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.", objectives = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24734] = { id = 24734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost!", description = "You've got to help me, {name}! My friend, Ringo left earlier to explore the volcano to the north of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", progress = "Ringo's sack rests on the rock in front of you.", completion = "You find what appears to be Ringo's belongings.  If he left these here, he can't have gone far away.  Maybe you should look for him.", objectives = "Find signs of Ringo at Fire Plume Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24735] = { id = 24735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Stand. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so you can slap me if I'm feeling woozy.  If I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", progress = "I've been so worried about Ringo...", completion = "Ringo's not in the best shape, {name}, but I am glad to have him back in one piece!\n\nThank you for finding him.", objectives = "Lead Ringo to Spraggle Frock at Marshal's Stand.\n\nIf Ringo feels weak, slap him. If he faints, use Spraggle's Canteen to revive him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24736] = { id = 24736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax in the Screaming Reaches to the west would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", progress = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!", completion = "Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!\n\nThanks!", objectives = "Collect 35 Webbed Pterrordax Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24737] = { id = 24737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, {name}. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nWe're going to be making some glue. Head to the tar pits just north of here, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. As a bonus, if you use my tar scraper on their corpses, you'll keep your hands nice and clean.", progress = "Tara's done it again -- this super sticky glue will be all the rage!", completion = "Yeah, this tar is pretty sticky, I guess.  I mean, it's sticky, but it's not \"make fistfuls of money\" sticky.  I guess I'll have to keep thinking.", objectives = "Collect 8 samples of Super Sticky Tar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24738] = { id = 24738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Williden's Journal", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the central part of the Crater; according to the journal, he and his companions sought to take a more offensive stance once their refuge was attacked.", objectives = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24739] = { id = 24739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Salvation", description = "I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Now that our camp is more centrally located, it will be much more convenient for us to do many things... such as retrieving some long-forgotten supplies.\n\nWe've left some old supplies at deserted base camps both northeast and southwest of here.  You look like you're capable enough - can you help us by getting them back?", objectives = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24740] = { id = 24740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanic Activity", description = "Welcome.  I'm Williden Marshal, and my sister and I run this expedition of explorers and scientists.  You have a moment?\n\nI don't like the look of those elementals on that volcano, {class}.  We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage.\n\nShow them that their new neighbors aren't to be trifled with.  And bring back the ash that they leave behind... we might as well do a little science while we're at it.", progress = "Do you think the volcano is active?  I wonder why it didn't explode when the cataclysm hit.", completion = "I hope that did the trick.  I'll take the ash... this may come in handy sometime down the line.", objectives = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24741] = { id = 24741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Up", description = "Hobart thinks he's going to feed us on those tiny clucker eggs? Bah! We're going to get some real eggs!\n\nI've already set up some traps on the Raptor Rise up the path to the east. Take this bunch of wild clucker eggs and lay them in the traps. The spiny raptors will go right after the clucker eggs, and then you'll get to trade up to their larger eggs.\n\nGenius!", progress = "How many did you get? I can just taste the massive omelet we're going to cook up now!", completion = "Nice! Look at the size of those things!\n\nThere's no way that Grapplehammer's going to be able to top those!", objectives = "Gather 5 Spiny Raptor Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24742] = { id = 24742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Source", description = "I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest lava flows.  It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!\n\nHot spots usually take the form of a glowing, rocky pillar jutting out of the ground.  You'll find them around the base of Fire Plume Ridge... one trip around the perimeter will likely suffice.", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "These results are astounding!  My boss will be pleased.  Thank you, kind {race}!", objectives = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, use the thermometer to check the temperature. Keep looking until you find the hottest one.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow's Edge", objectives = "Listen well, {class}. In accepting this weapon your fate is sealed.\n\nOvercome or succumb.\n\nI have placed your feet upon this path. You are therefore my personal responsibility. Should you failter, I am duty-bound to deliver you from this life.\n\nRemember my words, {race}, and do not fail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24744] = { id = 24744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Biggest Egg Ever", description = "Bamm Megabomb? Who does he think he is? His spiny raptor eggs are no match for what we are about to recover!\n\nAs you well know, each Town-In-A-Box is equipped with a micro mechachicken for just such a dietary emergency. Luckily for us, my keen intellect was able to deduce the location that our prodigious, pre-programmed poultry ran off to.\n\nHead north to the Scorched Gully. But beware, its circuit boards are fried and I imagine it's not so micro any longer!", progress = "Just think about the accolades that will rain down upon me... us, when the Biggest Egg Ever is returned!", completion = "Eureka! My genius saves the day yet again! Take that Bamm Megabomb!\n\nAnd now, to reap the benefits!", objectives = "Recover the Biggest Egg Ever.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya.", objectives = "Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24746] = { id = 24746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24747] = { id = 24747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage!", description = "These dwarven artillery shells have a built-in airburst timer. This is easy! Just sabotage one of the artillery shells in the loading bay and then hoist it up into the magazine. Boom, baby. BOOM!\n\nYou'll find the shells in one of two loading bays behind the main garage on this level. It's right around the corner.\n\nOnce you've rigged the artillery shell... Run! Run like the wind, {name}! Then report to Gann back at camp. I'll be right behind you.", progress = "<Gann only opens his eyes after you prod him. His breathing is little more than a series of shallow gasps.>", completion = "Bael'dun? Destroyed?\n\n<Wincing in pain, Gann twists his head to peer behind him, where plumes of smoke darken the skyline.>\n\n{name}, my friend. You have avenged Taurajo and avenged the Tauren people. The invaders will not soon recover from that blow. Thank you.", objectives = "Sabotage a Dwarven Artillery Shell and then flee from Bael'Dun before it explodes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24748] = { id = 24748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Last Stand", description = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.\n\nWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.\n\nTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.\n\nSteel yourself, {class}, and guide Shadowmourne to fulfill the purpose of its creation.", completion = "So, at last it is done.\n\nMay the people of Azeroth remember our deeds here forevermore. May the sacrifices of so many burn in their hearts eternally. May they never fail to risk mortal peril in the face of great evil.", objectives = "Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Infusion", description = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.\n\nYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.\n\nFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", progress = "Is it done, {race}?", completion = "Well done, {class}.\n\nThe completion of our work draws near.", objectives = "Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24750] = { id = 24750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Soratha to the east.", completion = "Anotha newblood, eh?\n\nYa actually have an intense look about ya though. Fiery eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Soratha in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24751] = { id = 24751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the arcane arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24752] = { id = 24752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Mage", description = "As ya' develop ya' powah, ya' gonna start to tink of new spells, new ways to use ya' arcane talents. \n\nGo now, grow ya' skills, and 'den come back an' show me what 'cha figure out.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach level 3 to learn Frost Nova. Practice using it 2 times against a Tiki Target.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24753] = { id = 24753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24754] = { id = 24754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24755] = { id = 24755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", objectives = "Report to Vol'jin at Darkspear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Infusion", description = "Your weapon is ready to be endowed with the power of blood.\n\nYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, {race}.\n\nOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.\n\nMay her screams pierce the ears of the Lich King as he awaits his fate.", completion = "Well done, {class}.\n\nShadowmourne is nearly within reach.", objectives = "Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Infusion", description = "Shadow's Edge is prepared to receive its final infusion of power.\n\nSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.\n\nWithout his dragon, nothing shall stand between you and the Lich King.", completion = "The axe has drunk its fill, {race}, and the forge is nearly ready for the creation of Shadowmourne...", objectives = "Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24758] = { id = 24758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nekali to the east.", completion = "Anotha newblood, eh?\n\nYa actually have a weathered look about ya though. Wise eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Nekali in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24759] = { id = 24759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the natural arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", progress = "Power isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24760] = { id = 24760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Shaman", description = "As ya grow in powah, you begin ta discovah the voices of da ancestahs speakin' to ya, teachin' you dere secrets.\n\nTha first of 'dese is to focus tha power of da elements into yer weapon. It allows ya to unleash a quick, vicious attack on your enemies. Dis should be easy enough for ya to make a lot of use of it.\n\nTry it out. Let me know when ya tink you have it down.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach Level 3 to learn Primal Strike, and then use Primal Strike 3 times against a Tiki Target.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24761] = { id = 24761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24762] = { id = 24762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24763] = { id = 24763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", objectives = "Report to Vol'jin at Darkspear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24764] = { id = 24764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zen'Tabra to the east.", completion = "Anotha newblood, eh?\n\nYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Zen'Tabra in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24765] = { id = 24765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the druidic arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", progress = "Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. This'll become more apparent as ya learn animal forms, but it holds true even now. Everytin' has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya casts - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24766] = { id = 24766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Druid", description = "As ya grow in powah, ya ability to call on nature gets strongah, too. Ya wanna see?\n\nGo get some experience and show me what ya' learn.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach level 3 to learn Moonfire. Practice using it on a Tiki target in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24767] = { id = 24767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
