quests[24770] = { id = 24770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Legati to the east.", completion = "Anotha newblood, eh?\n\nYa actually have a sly look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Legati in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24771] = { id = 24771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dose weapons you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", completion = "Not bad, mon. Ya have a natural flow to ya swings - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24772] = { id = 24772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Rogue", description = "As ya fight ya enemies, ya will learn new tricks you use ta be even bettah'. \n\nThere's one ya should be learnin' soon to let ya see dere weaknesses and set up for devastating combo attacks. After ya've struck a few blows to weaken ya foe, finish dem off with a vicious evisceration attack.\n\nWhen ya learn it, try it out. Let me know when ya tink you have it down.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach level 3 to learn Eviscerate, then use Eviscerate 3 times against a Tiki Target.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24773] = { id = 24773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
