quests[24776] = { id = 24776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Ortezza to the east.", completion = "Anotha newblood, eh?\n\nYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Ortezza in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24777] = { id = 24777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta use dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", progress = "Aim isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya attacks - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24778] = { id = 24778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Hunter", description = "As ya' start to get da hang of tings, ya gonna figure out how ta do new tricks.\n\nOne of da' first ya gonna learn is to keep a steady hand between shots, or else ya gonna find yaself exhausted and not really managin' to kill much.\n\nGo get some more experience 'till ya figure it out, 'den come back and try it out. Let me know when ya tink you have it down.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach level 3 to learn Steady Shot. Use Steady Shot 5 times on a Tiki Target.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24779] = { id = 24779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24780] = { id = 24780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24781] = { id = 24781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", objectives = "Report to Vol'jin at Darkspear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24782] = { id = 24782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Tunari to the east.", completion = "Anotha newblood, eh?\n\nYa actually have a balanced look about ya though. Calm eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", objectives = "Meet with Tunari in the Darkspear Training Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24783] = { id = 24783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the holy arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", objectives = "Destroy 6 Tiki Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24784] = { id = 24784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learnin' tha Word", description = "As ya get more skill out there in tha' world, you'll start to discovah' new powahs.\n\nWhy dontcha go out an' go get yaself stronger, and come back when ya learn sometin' new. You can show me what ya learn.", completion = "Good work, mon! Dis stuff come easy to ya.", objectives = "Reach level 3 to learn Shadow Word: Pain. Use it 5 times on 5 Tiki training dummies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24785] = { id = 24785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", objectives = "Retrieve 6 Wildmane Cat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
