quests[24823] = { id = 24823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Destruction", progress = "You seek to continue down the path of destruction?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24824] = { id = 24824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Disturbed Earth", description = "We are here to monitor the scars of the land, and watch for further signs of instability.  While we haven't seen any yet, a cataclysmic aftershock could devastate the Barrens even further.\n\nTo the northeast, near the chasm, earth elementals rampage out of control. To soothe the earth, these need to occasionally be destroyed, and their essence returned in a ritual. If you help us do this, {class}, I would be happy to reward you.", progress = "The elements must be carefully balanced, so returning the essence is key.  I hope you've been collecting it...", completion = "Thank you, friend. It's important we try to calm this earth in every way we can.", objectives = "Collect 4 Disturbed Earth Fragments from Disturbed Earth Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24825] = { id = 24825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Wisdom", progress = "You seek to continue down the path of wisdom?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24826] = { id = 24826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Vengeance", progress = "You seek to continue down the path of vengeance?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24827] = { id = 24827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Courage", progress = "You seek to continue down the path of courage?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24828] = { id = 24828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Destruction", progress = "You seek to continue down the path of destruction?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24829] = { id = 24829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Destruction", progress = "You seek to continue down the path of destruction?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nThe enemy speaks of your name only in whispers, for they know you're a force to be reckoned with.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24830] = { id = 24830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Wisdom", progress = "You seek to continue down the path of wisdom?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24831] = { id = 24831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Wisdom", progress = "You seek to continue down the path of wisdom?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nYou are a bastion of wisdom and our allies speak of you with the greatest reverence.  Many of them owe you their own lives.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24832] = { id = 24832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Vengeance", progress = "You seek to continue down the path of vengeance?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24833] = { id = 24833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Vengeance", progress = "You seek to continue down the path of vengeance?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are vengeance incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24834] = { id = 24834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Courage", progress = "You seek to continue down the path of courage?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24835] = { id = 24835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Courage", progress = "You seek to continue down the path of courage?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nYou are a source of inspiration to our allies and your unshakeable valor gives pause to even the most seasoned of our enemy's generals.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[24836] = { id = 24836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, <brother/sister>." }
