quests[24848] = { id = 24848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fireworks At The Gilded Rose", description = "Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.\n\nNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.\n\nI got a tip from a reliable source that Snivel's here in Stormwind, livin' it up at the Gilded Rose. What's more, he had some dame on his arm. Marion Sutton was the name. Go to the Gilded Rose and see what she knows.", completion = "You... You're not Snivel. Did he send you? He's so late, I had started to give up hope...\n\n<Tears start welling up in the woman's eyes once she realizes that you aren't there to deliver a message from Snivel.>\n\nThat's not like my Snivel, but what other choice is there?", objectives = "Speak to Marion Sutton at the Gilded Rose in Stormwind's Trade District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24849] = { id = 24849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On The Trail", description = "I'd better start from the beginning. It was love at first sight, {name}. There was just something about that goblin from the moment I set eyes on him.\n\nAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?\n\nAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!", completion = "All he talked about was leaving town with all his money? Then he really has abandoned me, hasn't he?\n\nOh, {name}, I was such a fool to fall for him, but how could I help myself? He was so irresistible!", objectives = "Look for Snivel Rustrocket in the Stormwind Counting House, the Auction House, and the Barbershop in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24850] = { id = 24850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snivel's Sweetheart", description = "Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.\n\nNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.\n\nI hear Snivel's livin' it up here in Orgrimmar. What's more, he's got himself a girlfriend -- some orc dame named Roka. She's supposed to meet him at Gotri's Traveling Gear in the Drag before they make their escape.", completion = "You're not Snivel. He was supposed to be here an hour ago! What have you done with him?\n\n<Roka seems to calm down when you tell her that you're looking for Snivel, too. Then, tears start to well up in her eyes.>\n\nThis isn't like my sweet Snivel. Do you think something's happened to him?", objectives = "Speak to Roka at Gotri's Traveling Gear in Orgrimmar's Drag district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24851] = { id = 24851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On The Trail", description = "I'd better start from the beginning. It was love at first sight, {name}. There was just something about that goblin from the moment I set eyes on him.\n\nAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?\n\nAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!", completion = "All he talked about was leaving town with all his money? Then he really has abandoned me, hasn't he?\n\nI can't believe I fell for such a horrible goblin! But he was so irresistible when we first met.", objectives = "Look for Snivel Rustrocket in the Orgrimmar Bank in the Valley of Strength, the Auction House, and the Barbershop in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24852] = { id = 24852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Tribe, Imprisoned", description = "Despite their size, the Bristleback greatly outnumber us. A pack ambush can easily overwhelm even the largest tauren.\n\nMany new initiates have taken up arms to defend our home. Some have given their lives, but others have been captured alive.\n\nPlease, find their cages and free them. The battle should keep the quilboar distracted.", progress = "Not enough have returned, {name}. Return and free more of our people. Be brave!", completion = "Thanks to you, our people are free to fight for our home.", objectives = "Open 4 Quilboar Cages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24854] = { id = 24854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Stormclaw", description = "Zen'Aliri been studyin' the ways of the druid, {race}.  Hopefully one day, Zen'Aliri join the Druids of the Talon, and soar over this crater as a storm crow.\n\nBut for now, my mentor says I stay here and wait.  So Zen'Aliri waits.\n\nI know another druid who might be able to use your help.  His name is Garl Stormclaw, and he's somewhere to the east of here, studying reagents.  Maybe you go talk to him?", completion = "Zen'Aliri was wise to send you here.  I've hit a dead end in my studies.", objectives = "Report to Garl Stormclaw at the entrance to Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24855] = { id = 24855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrant Flora", description = "Look how strangely the plant life reacts to the bloodpetals in the Roiling Gardens to the north.  The trees are enveloped with more flowers and vines than usual.  Large, sporous blossoms project themselves from the ground where they once did not.\n\nThe land is speaking to us, {race}.  The bloodpetals are destroying the balance.\n\nAs my final task, I ask you to visit the swarming adult bloodpetals and prune their numbers.", progress = "We cannot move forward until you have put an end to the bloodpetals, {class}.", completion = "The scent of bloodpetal pollen hangs about your head, {class}.  This is good.\n\nYou've earned your reward.", objectives = "Kill 11 Bloodpetals. Any type of adult Bloodpetal will do.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24856] = { id = 24856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Imminent!", description = "Your work here is done for now, but there's no rest for the wicked, eh?\n\nYou remember Megs Dreadshredder, our old marketing rep? She's taken some others over the hills to the southeast, just past the Raptor Rise. If you follow the path east out of town and follow it south at the fork, you can't miss her.\n\nApparently there's some trouble or other brewing with the snake-men at the ruins on the shore. Go see if you can't sort it all out, would you?", completion = "Boss, we gotta problem.", objectives = "Speak with Megs Dreadshredder at the western entrance to the Ruins of Vashj'elan on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24857] = { id = 24857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", progress = "You have a look of concern about you, {name}. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many {race}, {name}.", objectives = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24858] = { id = 24858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewater Cartel Represent", description = "Looks like the naga down there in the ruins are preparing to invade our Town-In-A-Box. I have lots of dead scouts here as proof.\n\nI don't know about you, but I'm not about to let them try. Let's get the jump on them!\n\nCould you lay the foundation for our new coastal holdings by replacing their banners with our own? That's some prime real estate down there!", progress = "There are still some naga banners down there that need to be 'sploded and replaced!", completion = "I wish I could have seen the looks on their scaly faces when you blew up their banners and replaced them with our own.\n\nOn second thought, I don't want to be close enough to see their snarls.", objectives = "Destroy 10 Naga Banners, replacing them with Bilgewater Cartel Banners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24859] = { id = 24859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Hide", description = "It's oft whispered in dark corners of a material so fine, so exquisite to the touch, that goblins of sophisticated taste will spend any amount of moolah to get their hands on some.\n\nOf course, I'm speaking of naga hide!\n\n<Brett looks around to make sure no one else is listening in.>\n\nI know that you're going to head down there and that it's inevitable that you're going to have to fight those snakes. Hey, they're not going to have a use for their hides anyway. They'll be dead!", progress = "Well? How many do you have for me? I think that a 95 to 5 split is more than generous.", completion = "We're going to be filthy rich, I tell you! Well, if we can get off of this island, that is.", objectives = "Collect 5 Intact Naga Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24860] = { id = 24860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profitable Preservation", description = "You know, the naga are the mutated and prettier versions of the kaldorei, better known as the night elves. Don't ask me... it's a long story.\n\nSuffice to say that I'm sure you could 'procure' an artifact or two while you're down there in the ruins. If you know what I mean?\n\nWe have to preserve them in the homes of wealthy collectors everywhere! Right?", objectives = "Collect 12 Kaldorei Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24861] = { id = 24861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Rites, First Rites", description = "The camp is safe, and the quilboar driven off, all thanks to you, young one. You have my personal thanks for what you have done for my mother, my son, and for all of us.\n\nIt is now time to put Greatmother Hawkwind to rest. Lay the final offering at her feet, {name}, and we will say our goodbyes.", progress = "Do not be shy, {name}. I am honored to have you lay the final offering.", completion = "There is balance in all things. As Greatmother Hawkwind's spirit takes its final journey, you will begin your first.", objectives = "Use the Ceremonial Offering at Greatmother Hawkwind's grave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24862] = { id = 24862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running the Gauntlet", description = "Look around you, {class}. We've had no luck dislodging the Horde from the hidden trails that overlook this valley. They appear out of nowhere to ambush our supply caravans and then disappear into the hills!\n\nI need you to run the gauntlet to Honor's Stand and let them know the roads still aren't safe. Talk to Mattingly, the supplies officer by the gate.\n\nAnd kill a few of these brutes along the way!", completion = "They're ambushing the roads to Stonetalon, too? We just can't get a break here. Where are they coming from, anyways?", objectives = "Kill 8 Hunter Hill Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24863] = { id = 24863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Siege", description = "Horde scouts hiding in the ruins up ahead ambushed my supply train. Only two of my bodyguards made it out of there alive. And me? I used to have hair!\n\nThe supplies I was delivering are scattered through the ruins up ahead. Gather them up and take them to Janice Mattingly at Honor's Stand. If they can't make it to Stonetalon, at least we can keep them out of Horde hands...", progress = "What's the story out there?", completion = "What ... our supplies? These were meant for Stonetalon.\n\nNo matter, at the rate we're going, we need them more here. Honor's Stand has been cut off from the coast, {name}. Commander Singleton is at his wit's end.", objectives = "Gather 10 Stonetalon Supply crates from the ruins west of Honor's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24864] = { id = 24864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irresistible Pool Pony", description = "I've got a plan and you're the only one that I know crazy enough to pull it off!\n\nI need you to take this irresistible pool pony to the Vashj'elan Spawning Pool and inflate it. Then, swim down to their hatchlings with it on. I'll bet anything that the hatchlings can be lured away to follow you.\n\nBring them back here and we'll proceed with the next phase of the plan.", progress = "That's not enough hatchlings.", completion = "Oh, they're so cute! I wish that we could turn them into little plush toys and sell them for a gazillion macaroons!", objectives = "Use the Irresistible Pool Pony to lure 12 Naga Hatchlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24865] = { id = 24865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This Stuff Still Good?", description = "You find what appears to be a crate of food, left behind when this camp was abandoned.  On the outside of the crate, you can make out a stamp that says \"PROPERTY OF MARSHAL EXPEDITIONS\".\n\nPerhaps you might find someone who could use this?", progress = "What have you got there?", completion = "Oh... wow... it's some really old food.  Hey Hol'anyee, take a look at this!  This {race} brought us those old rations that we abandoned!\n\nNo, not from Marshal's Refuge... from the old base camp!\n\n\n\nI'm not sure I want to peek inside.  I'll just give it to Nolen, I guess... he'll know what to do with it.", objectives = "Return the Crate of Foodstuffs to Williden Marshal at Marshal's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24866] = { id = 24866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abandoned Research Camp", description = "You find what appears to be a piece of research equipment, left behind when this camp was abandoned.  Chiseled onto the side of the device are the words \"PROPERTY OF MARSHAL EXPADISHUNS\".\n\nPerhaps you might find someone who could use this?", progress = "Yes, {name}?", completion = "Well I'll be... that's Shizzle's old portable dinomometer!  Where did you find this?\n\nI'm surprised it's still functional, even after all these years.  I'll have it delivered to Shizzle promptly.", objectives = "Return the Research Equipment to Hol'anyee Marshal at Marshal's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24868] = { id = 24868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrender or Else!", description = "{name}, you and Ace need to march those naga hatchlings down there and use them as leverage to convince the leader of the naga to surrender to us.\n\nAce knows where to go on the south side of the ruins... just follow him.", progress = "What's wrong?", completion = "A faceless of the deep? What's that? That does NOT sound like a naga!\n\nWell, you killed it, whatever it was. It doesn't matter now. We have other fish to fry....", objectives = "Deal with the leader of the Naga at the Ruins of Vashj'elan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24869] = { id = 24869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deprogramming", description = "We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.\n\nOur man, Darnavan, is one of them now.\n\nIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.", objectives = "Defeat Lady Deathwhisper while ensuring that Darnavan survives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24870] = { id = 24870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", objectives = "Slay the Rotting Frost Giant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24871] = { id = 24871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", objectives = "Slay the Rotting Frost Giant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24872] = { id = 24872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respite for a Tormented Soul", description = "Take this Life Crystal, and have your companions take one as well. It contains potent energies from the verdant Dragonshrine in Dragonblight, and it was my own secret to resisting the dark magics of this place for so long.\n\nWhen you face Sindragosa, battle her until she is weakened, and then have your companions use these Crystals to coax out the essence that is dormant within her. If you then defeat her, you should be able to recover it and return it to Wyrmrest Temple in Dragonblight.", objectives = "Use the Life Crystals to preserve Sindragosa's Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24873] = { id = 24873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Residue Rendezvous", description = "Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.\n\nBut there's a catch -- a proper sample will need to mix two active strains within a living host. Should you have the... misfortune... of becoming such a host, please return here immediately so that we can harvest you for study.", objectives = "Return to Alchemist Adrianna while infected with Orange and Green Blight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24874] = { id = 24874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Quickening", description = "These Scourge bloodsuckers -- San'layn they call themselves - give me the creeps. We've had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He's being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it's too late!", objectives = "Rescue Infiltrator Minchar before he is executed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24875] = { id = 24875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deprogramming", description = "We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.\n\nOur man, Darnavan, is one of them now.\n\nIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.", objectives = "Defeat Lady Deathwhisper while ensuring that Darnavan survives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
