quests[24896] = { id = 24896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random 65-70 (Nth)" }
quests[24897] = { id = 24897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back to Town", description = "We were wrong. It wasn't the naga that were preparing to attack... it was the nearby Oomlot tribe.\n\n{name}, you need to get back to the Town-In-A-Box. The pygmies are already attacking!\n\nHere, take this. We bought it off of a pygmy who said it used to belong to some great leader of theirs. Someone whose name translates as Dark Tan Helmet.\n\nIt should fool them so that they don't attack you.", completion = "{name}? We're saved!\n\nWho am I kidding? We're all going to die!!!", objectives = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24898] = { id = 24898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going, Going, Guano!", description = "There be more in the Razorfen than just pigs, <bruddah/sistah>. There be bats as well...and if you're goin in there and rilin' up the quilboar anyway, I want ya to bring me back some guano.\n\nYah, guano. The droppin's. Don't give me that look. It be foul, but powerful, primal stuff for rituals...rituals to keep the earth 'round here strong enough to keep from rippin' apart under all the damn fools warrin' round here.\n\nJust bring Zan'do one pile of guano, yah?", objectives = "Bring 1 pile of Kraul Guano to Zan'do at Firestone Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24899] = { id = 24899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going, Going, Guano!", description = "As you can see, {name}, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a {class}. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...", objectives = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24900] = { id = 24900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueleaf Tubers", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.", objectives = "In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24901] = { id = 24901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Town-In-A-Box: Under Attack", description = "{name}, you have to defend us!\n\nI had the eggheads deploy the town's cannon defenses, but it seems like there's an unlimited supply of these Oomlot warriors!\n\nGet your behind into one of those B.C. Eliminators and eliminate the pygmy threat to the town!", progress = "That's not enough, hon. Can you take care of more of them?", completion = "Okay, I think that's good enough for now, but they took a bunch of the townsfolk captive.\n\nWe're going to have to take the fight to them!", objectives = "Use a B.C. Eliminator to defeat 30 Oomlot Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24902] = { id = 24902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt For Sylvanas", description = "It's true then?  Gilneas has lost her favorite son.\n\nWe will mourn when this is all over but not a day sooner.\n\nWe will not allow ourselves the luxury of grief while the enemy still breathes Gilnean air.\n\nMy father's men are ready to strike while we still have the Banshee Queen's trail.  Just say the word if you're ready.  Liam deserves swift vengeance.", progress = "Did you find her, {name}?", completion = "The Plague?  Something so heinous that not even the orcs condone its use?  I'd say this warrants notifying King Greymane.", objectives = "Follow Tobias Mistmantle in the Hunt for Sylvanas.\n\nIf you lose Tobias, return to Lorna Crowley and speak with her to call again for his aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24903] = { id = 24903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance or Survival", description = "Tell Greymane that we have trackers on Sylvanas and tell him about the Plague.\n\nThe decision will be his.  Launch an all out attack against the leader of the Forsaken or try to evacuate our survivors.", completion = "You present me with the most difficult choice of my life, {name}.", objectives = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24904] = { id = 24904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Gilneas City", description = "The time has come, {name}.  We've rallied and armed every available Gilnean.\n\nIt is time to meet the enemy head on.  Time to settle the score with Sylvanas and her Forsaken dogs once and for all.\n\nLiam is heading the assault from this gate.  King Greymane and my father are leading the assault on the other districts.\n\nYou have a crucial role to play in this as well.  Take this rapier.  Use it to inspire our men and women in combat.  Speak to Krennan Aranas to take part in the battle for Gilneas City.", progress = "No...", completion = "We've driven the Forsaken back.  We hold three out of the four districts.\n\nBut at what cost...", objectives = "Achieve victory in the Battle for Gilneas City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24905] = { id = 24905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning a Favor", description = "You know, while you were out doin' your thing, Megs stopped by here. I hadn't seen her in months, but she barely gave me the time of day, just wanted me to tell you she had more business lined up.\n\nShe said she was headed over to the Dunemaul Compound to set up shop, something about ogres. Since you're done here, might as well head over...I wouldn't keep a goblin like her waiting.", completion = "I've got a great one for you this time, {name}. We're gonna initiate these ogres into the Horde...working directly under us.", objectives = "Find Megs Dreadshredder at the Dunemaul Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24906] = { id = 24906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seaside Salvage", description = "We've got to get goods moving in this market ASAP if we want to be competitive. I've got an angle for us.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nHead down there and start salvaging; there's crates full of pure profit just floating around down there.", progress = "Let's see what you've got.", completion = "Hmm, mostly usable. This is good stuff. I've already got buyers lined up, of course.\n\nHere's your advance for the rest of the work you're gonna do for me and the Bilgewater Cartel...partner.", objectives = "Collect 7 Steamwheedle Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24907] = { id = 24907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puddle Stomping", description = "Here's the situation. If we want to establish the Bilgewater Cartel's market presence in Gadgetzan, we'll need to start providing services to the community.\n\nThe new coast has been great for business here, but the sea also brought sea giants with it. They're large, foul, and drive real estate values down.\n\nHead to the shallows just south of town and kill as many as you can, and I'll cut you in on some of the deals I'm brokering here.", completion = "Property values have already gone up since you left. People like seafront views that don't include briny, gnarled giants stomping around.\n\nHere's your cut, {name}.", objectives = "Kill 8 Tidal Striders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24910] = { id = 24910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Rescue", description = "Alright, {name}. We've done enough small jobs around here; it's time to seal the deal.\n\nThe ruins of Steamwheedle Port are still full of hapless Steamwheedle goblins, waiting to be rescued. Every single one of them is a potential future customer. They're firing on every boat that leaves port...so I say we take to the skies!\n\nThere's a hot air balloon just outside of town near the docks, we can use that. Go ahead and hop in, I'll catch up with you.", progress = "What's with the premature bail-out? We gotta get back out there.", completion = "Isn't it nice when you can do a good deed, and see enormous future financial gains from it? It warms my little goblin heart. And my big goblin wallet.\n\nYou did great, kid. Gadgetzan's gonna be ours soon. Here's a little token of my appreciation.", objectives = "Deliver Life-Rockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southshore Blockaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24911] = { id = 24911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tropical Paradise Beckons", description = "Hey, you look like a discriminating adventurer.  Are you looking for something different?  Something exotic?  Something... profitable?\n\nWell shake the sand out of your boots, because I've got a proposition for you.  Williden Marshal is looking for competent sellswords such as yourself.  He's set up camp at Marshal's Stand, just southeast of the volcano in the center of lush Un'Goro Crater.\n\nThen again, paradise isn't for everyone, {race}.  It's up to you.  Your tropical oasis awaits.", completion = "Hey Hol'anyee, look at the getup on this one!\n\n<Williden turns to face you.>\n\nAhem.  Our recruiter sent you?  Good.  Let's start out with a bit of honesty: Un'Goro isn't the perfect nirvana that you may have been promised.  You've probably figured that out on the way over here, though.\n\nShall we get to work?", objectives = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24912] = { id = 24912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowerment", progress = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", completion = "Stand Clear, {class}, and steady yourself." }
quests[24913] = { id = 24913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember the Light", description = "Magtoor grows weaker by the second, {name}. My remedy is prepared... it must work. It must!\n\nYou have done so much for the both of us. I would be honored if you stayed for what may be Magtoor's final moments.", completion = "I am moved, {name}. Prophet Velen has been in closely guarded seclusion. He has dared not waste his energy on anything save preparing for the final confrontation he has foretold.\n\nAnd yet, he came here, in person, to comfort a single dying soul.\n\nI must thank you as well, for helping me make my last effort to comfort my friend. My research will continue... and I hope that Magtoor will continue to watch over me.", objectives = "Help Anchorite Avuun say farewell to Magtoor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24914] = { id = 24914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Property", description = "You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.\n\nIf anyone could know the method of its opening, it would be Highlord Mograine.", completion = "<After tracing a complex pattern of runes on each of the box's surfaces, the outline of a lid appears and a click echoes through the chamber.>\n\nHere you are, {race}.", objectives = "Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24915] = { id = 24915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mograine's Reunion", progress = "What is that you hold, {class}?\n\nIt calls out to me, stirring feelings I thought to be long dead.", completion = "Impossible...\n\nFather, is it you?!\n\nYou have done me a great service, hero. I offer you the reins of my faithful steed. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24916] = { id = 24916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina's Locket", progress = "Yes, {class}? How can I assist you?", completion = "What... how did you manage to come by this!?\n\nYou have done me a great service, hero. My heart could not bear to keep this locket, but I will place an enchantment upon it that you may find useful. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24917] = { id = 24917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muradin's Lament", progress = "Whatdya got there, {race}?", completion = "Aye. I know this blade... and I will treasure it always - a moment of time that will be lost forever.\n\nYou have done me a great service, hero. I offer you a gift from the Frostborn dwarves. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24918] = { id = 24918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanas' Vengeance", progress = "What is it, {race}?", completion = "<Sylvanas silently reflects for a moment before returning her gaze to you.>\n\nYou have done me a great service, hero. I offer you the boon of the Banshee Queen. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24919] = { id = 24919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lightbringer's Redemption", progress = "How may I be of service, {race}?", completion = "<Uther stares at the medal, speechless for a moment.>\n\nArthas' medal.\n\nI remember well the day I presented it to him...\n\nYou have done me a great service, hero. My soul may now rest in peace. I offer you a memory lost in time. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24920] = { id = 24920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slowing the Inevitable", description = "As much as I want to exact swift and brutal revenge... I must honor my son's memory first.  He cared for his people first and foremost.\n\nThe Undertaker's Pass goes underground below Northgate River.  You must prevent the plague from being deployed while we evacuate our men, women and children to Aderic's Repose.\n\nWe captured one of the Forsaken's dreaded bombing bats.  I want you to fly the infernal beast as best you can and unleash hell upon those who seek to bring the Plague to our people.  Hurry!", progress = "Is it done, {name}?", completion = "You've done well, {name}.  Almost everybody managed to make it through.", objectives = "Use the Captured Riding Bat to destroy 6 Forsaken Catapults and 40 Invading Forsaken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24921] = { id = 24921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Aubrey", description = "You there! Fresh off the boat? Welcome to Kalimdor, a land hellbent to kill you or die tryin'.\n\nThere's trouble at the hold - as I'm sure you noticed on your way in. Admiral Aubrey needs all hands on deck if we're to make it through this. Consider yourself drafted, {class}!\n\nFollow the road up the hill and you'll find Aubrey in the tower, topside.", completion = "Hm? What unit are you with, {class}?\n\nNo matter, we need all hands. My fleet is in tatters and they've broken into the hold. You armed? That's good enough for me.", objectives = "Report to Admiral Aubrey in Northwatch Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24922] = { id = 24922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Burning Crusade - Heroic Random - 1st" }
quests[24923] = { id = 24923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Burning Crusade - Heroic Random - Nth" }
quests[24924] = { id = 24924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot Village", description = "The pygmies took most of our people back to their village. Who knows what evil they're up to?\n\n{name}, you have to go up there and free all of the captives before the pygmies work their voodoo on them!\n\nIzzy's already up near Oomlot Village to the southeast. She'll give you the heads-up on what's going down.\n\nYour pygmy helmet looks like it's in bad shape, but it should last long enough for you to get there.\n\nI hope.", completion = "{name}? What are you doing wearing that pygmy helm? Looks like it's about to fall apart.\n\nI'm glad that they sent you up here. I thought for sure they were going to send that jerk, Grapplehammer and his ego-enabling assistant.", objectives = "Speak with Izzy at Oomlot Village on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24925] = { id = 24925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Captives", description = "They've got a bunch of our people in there. I know that they're doing strange rituals to them. It looks like they're sucking the life force right out of them!\n\nYou have to go into the village and free the captives before it's too late!", completion = "Great job, but that's not even half of the hostages that they took from town.\n\nDarn it all! They must have taken the rest of the captives to their other villages up in the volcano!", objectives = "Free 5 Goblin Captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24926] = { id = 24926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving A-Me 01", description = "Greetings.  I unit A-Me 01.  You... {race}?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data that Karna needs.\n\nA-Me 01 not returning, though.  A-Me has new family now.  Here, with the gorillas, A-Me stay.\n\n<A-Me 01 detaches a small device from her hand and gives it to you.>\n\nYou bring data back to Karna.  You tell her what happen.", progress = "Wh... what's this?", completion = "She decided to stay?  Fascinating... I'll have to look over this data and find out why.\n\nThank you again, {name}. I really appreciate it.", objectives = "Bring A-Me's Thumb Drive back to Karna Remtravel at Mossy Pile in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24927] = { id = 24927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Chest", description = "Look, babe, you should be able to see what's happening here pretty easily. There's pirates, there's goblins, the goblins are fighting the pirates. There's some sad little gnomes trying to fight the pirates too.\n\nI'll make it nice and simple for you: we need to kill a lot of pirates. Go do that, 'kay? We don't want the gnomes killing more than us, after all.", completion = "I'm pleased to report that our brand recognition in this area has skyrocketed now that you've killed most of the people who didn't want us here.", objectives = "Kill 15 Southsea Freebooters of any kind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24928] = { id = 24928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Ground!", description = "I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate.\n\nLuckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there.\n\nTry not to stand downwind.", completion = "Wonderful job. Have you ever thought about becoming a full-time arsonist? I know a few people, it's a nice gig.\n\nWell, we'll chit-chat about that one later. More to do here!", objectives = "Set fire to the Northwest Shack, the Southeast Shack, and the Northeast Shack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24929] = { id = 24929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send a Message", description = "The Oomlot leader, Yngwie, is too powerful to be left alive. He's barking nonsense from the raised west side of the village, across the rope bridge.\n\nGo up there and get him before he sends the rest of the village against us.\n\nPiece of cake!", completion = "Nice work, bud! Hope he wasn't too tough.", objectives = "Slay Yngwie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24930] = { id = 24930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While You're At It", description = "Fine by me if King Greymane wants you to risk your life to rescue a known traitor.\n\nDo me a favor and do something useful while you're out there and kill these cursed fleabags.", progress = "What is it then, {name}?", completion = "If I hadn't seen you kill a few of the mangy things with my own eyes, I'd think you did not complete the task I asked of you.\n\nIt looks like we're hardly putting a dent in their numbers.", objectives = "Kill 5 Bloodfang Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24931] = { id = 24931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazer Tag", description = "You're going out to hunt hyenas, eh? If you don't mind, I've got an offer myself. I'm in need of eyes from the Glasshide Gazers that lurk to the north. Their eyes contain wonderful crystals, valuable to...collectors.\n\nNow, you may have heard that some sad individuals use these to enhance paramental abilities, but I assure you, my interests are purely academic!\n\nBring me a good portion of them and I'll pay you well for them. Better than these copper-pinching goblins will, at least!", progress = "Do, ah, do you have them?", completion = "Ahh, perfect! Just what I need...full of potent focusing energies...\n\n...ahem! I mean, perfect for my collection! Narain Soothfancy is in no need of artificial enhancement of any kind!\n\nNow take your pay and be off!", objectives = "Collect 5 Ocular Crystals from Glasshide Gazers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24932] = { id = 24932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Losses", description = "I've spent the last week starin' at this ugly pit trying to think of how to exploit a bunch of dangerous, violent arthropods for profit. Now I'm out of ideas, and starving.\n\nThese things are a wash, and I say it's time to start clearing them out. Head down into that pit and start killin' bugs.", completion = "This isn't goin' fast enough. There's gotta be a faster way...", objectives = "Kill 15 Hazzali Silithid of any kind in the Gaping Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24933] = { id = 24933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken of the Desert", description = "I've got an idea, but we're going to need bait.\n\nThe other day I saw a rabid blisterpaw hyena wander too close to the edge of the chasm, and one of the silithid comes diving out of nowhere. Nearly swallowed it whole! Horrible sight.\n\nSo we're gonna need hyena meat, obviously. Go gather some, make sure it's fresh, and bring it back here. There should be plenty just north of the camp.", progress = "This is fresh, right? They won't go after anything that's been withering in the sun.", completion = "Man, this stuff looks delicious. I'm half tempted to just fry some up myself.\n\nNo! We've gotta focus on gettin' out of here.\n\nMaybe just one piece...", objectives = "Collect 6 pieces of Hyena Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24934] = { id = 24934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel Boarders!", description = "{name}, the sea is our only lifeline, and right now most of my fleet is either steaming back to Theramore for repairs or rusting at the bottom of this bay. Only the Blackpool remains afloat to defend our harbor.\n\nBut she's just signaled that she's being boarded!\n\nSpeak to me when you're ready, I'll have one of our naval gryphons deposit you right on the deck. Slaughter the rageroar sea dogs who dare assault my precious ship and report to Captain Fisher for further orders.", progress = "Blood! All over my freshly polished brass.", completion = "You make a hell of a marine, {name}.\n\nWe'll mop up the others. But it looks like the Horde fleet is disengaging - maybe to land more troops ashore?\n\nAdmiral Aubrey will know what to do. Talk to me when you're ready to fly back!", objectives = "Speak to Admiral Aubrey to fly to the Blackpool and kill 6 Rageroar Sea Dogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24935] = { id = 24935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body And Soul", description = "There are powerful and evil magics at work in this village. Yngwie, was tough. In fact, he was probably too tough.\n\nIf you were to drag his body down to the big blue bonfire and toss it in, you'd release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.", objectives = "Destroy Yngwie's Soul.\n\nIf you somehow misplace Yngwie's Body, ask Izzy if she found it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24936] = { id = 24936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body And Soul", description = "There are powerful and evil magics at work in this village, {name}. Yngwie, was tough. In fact, he was probably too tough.\n\nIf you were to drag his body over to the big blue bonfire and toss it in, you'd release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.", objectives = "Destroy Yngwie's Soul.\n\nIf you somehow misplace Yngwie's Body, ask Izzy if she found it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24937] = { id = 24937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot Dealt With", description = "{name}, you have to get back to the Town-In-A-Box and warn them about the goblin zombies up in the volcano's caldera!", completion = "They turned some of our people into zombies? Tell me something I don't know....", objectives = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24938] = { id = 24938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guns of Northwatch", description = "Captain Fisher signaled us from below. The Horde fleet is landing shore parties? We can't let them flank us from the beach.\n\nI've already sent two of my best gunners down there to defend the beach head. Talk to Cannoneer Smythe down on the shore.\n\nYou'll have to fight your way through the courtyard to get there. See if you can help the others secure the hold on your way down!", completion = "Aubrey sent you? Good! I take it you know your way around a cannon?", objectives = "Speak with Cannoneer Smythe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24939] = { id = 24939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Run Out the Guns", description = "We've got the hardware but not the manpower, {name}. Man one of the carronades on the shore here and take out those incoming boats!", progress = "Sure gets your ears ringing, doesn't it?", completion = "Ho ho! The beach is ours!\n\nWe just might keep a foothold on this miserable dustball of a continent after all.", objectives = "Use a Northwatch Shore Battery to destroy 10 Rageroar Rowboats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24940] = { id = 24940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up the Volcano", description = "A whole bunch of our people headed up to the top of the volcano to mount a counter-offensive. There's something horrible brewing up there on the Lost Peak.\n\nThey're waiting for you before they make any moves against the pygmies. Those evil little things turned a lot of us into zombies!\n\n{name}, save us!", completion = "My star player has arrived!", objectives = "Speak with Coach Crosscheck at the Lost Peak on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24941] = { id = 24941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langridge Shot", description = "{class}! Thank the Light - they've practically driven us back to the docks. The courtyard is overrun!\n\nWe're out of canister shot and the orcs are getting ready for an assault up the hill. We need to improvise some scatter-shot, and fast.\n\nHurry, run into the broken tower here and grab whatever sharp, pointy bits of scrap metal you can lay your hands on. Knives, forks, nails - anything! Load the cannon when you've got an armful!", progress = "Paxton has already loaded a charge into the cannon. All it needs is the ammunition you improvised.", completion = "The Horde is massing at the base of the hill. Breathlessly, you stuff the debris you collected into the muzzle of the cannon, step back, cover one ear, and tug on the igniter cord...", objectives = "Gather 15 pieces of Langridge Shot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24942] = { id = 24942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombies vs. Super Booster Rocket Boots", description = "Those zombies that got past us are nothing compared to the numbers waiting just through the pass. If we don't deal with them soon, the pygmy witch doctors are going to send all of them against the town, and even the cannons down there won't be able to handle that many!\n\nI brought a couple of shredder boots along. Greely modded them and now they're Super Booster Rocket Boots!\n\nUse the boots to incinerate the zombies in the Oostan villages to the east.", progress = "You still have a few {race} zombies to deal with, {name}. Look sharp, superstar!", completion = "You did it! No more zombies to worry about. Let's pause a moment in silence for the stinky departed.\n\nOkay, done.", objectives = "Use the Super Booster Rocket Boots to slay 50 Goblin Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24943] = { id = 24943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Take the Courtyard", description = "That's one way to clear a hill. Those corpses are impaled with knives and forks!\n\nThe Rageroar clan has breached the walls, but we can still turn this fight around. Go down the hill and help our men hold on to the courtyard below...", completion = "Great work! We've knocked them on their heels, maybe long enough to shore up our defenses.\n\nProvided we find a way to take out their artillery...", objectives = "Kill 10 Rageroar Grunts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24944] = { id = 24944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in the Fight", description = "This fight isn't over, {class}. Not by a long shot.\n\nSome of the soldiers in the courtyard still have breath in their lungs. We can save them! I've soaked these rags in an herbal remedy we used to rely on back in Gilneas. The smell is awful but this poultice can practically raise the dead.\n\nUse these bandages on wounded defenders down in the courtyard and we'll see if we can't get them back in the fight.", progress = "I hope you have enough bandages. My supply of those herbs was cut off when these brutes sacked my beloved Gilneas.", completion = "A steady stream of the walking wounded have come up the hill to see me, {name}. I trust that was your work? Well done!", objectives = "Use the Herb-Soaked Bandages on 6 Wounded Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24945] = { id = 24945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Little Pygmies", description = "Look, I think it's great that we're destroying all of these zombies, even though they're our friends and family. But don't you think we should be taking care of the pygmies that are creating them as well?\n\nAt the three Oostan villages, Nord, Sor, and Ost, there are witch doctors: Gaahl, Malmo, and Teloch.\n\nMaybe you could take care of them? I don't want to be turned into a zombie!", completion = "I gotta tell you, that's a load off of my mind. That is, I won't have to worry about no new zombies coming after my brains!", objectives = "Slay Gaahl, Malmo, and Teloch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24946] = { id = 24946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rockin' Powder", description = "I'll give these pygmies one thing... they sure know how to party! But they're not so clever. I think I've discovered the source of their rockin' powers: Rockin' Powder!\n\nIt turns out that this stuff, which turns them into world-class rockers, is also highly explosive. We must have it!\n\nSo, while you're in there at Oostan to the east, make sure that you pickup a whole bunch of the stuff. Trust me, you're going to need it for what's coming up!", progress = "Hmm, let me see how much you've got.", completion = "This will do. In fact, it's more than we need. I devised an ingenious idea for a weapon that the boots will be turned into once you get them to Hobart.\n\nHand the powder over and I'll load it into the the Super Booster Rocket Boots.", objectives = "Collect 5 scoops of Rockin' Powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24947] = { id = 24947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "We can't just rest on our laurels here, babe. We've got to keep this momentum going! People are talking about us.\n\nUnfortunately, they're also talking about this air-headed gnome, Kelsey, who's apparently been running jobs right alongside us. If we're going to drive her out of what's rightfully a goblin town, we need to seal the deal here.\n\nWe're going to take care of Gadgetzan's pirate problem for them, for good. Head south to Lost Rigger Cove, I'll meet you there.", completion = "Good thing you're here! I'm gonna need a lot of help if we want to beat these gnomes to the punch.", objectives = "Meet Megs Dreadshredder at Lost Rigger Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24948] = { id = 24948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Siege", description = "We'll never be able to re-secure the fortress walls so long as Rageroar and his goons have access to artillery. I need you to fight your way across that chasm and take out his big guns.\n\nOrcs season their heavy machinery with coal tar, which makes them flammable. Take my torch and burn any catapults you see north of Northwatch.\n\nThen, torch those big blade-throwers in Rageroar's base camp! Those things have killed enough of our men.", progress = "Burn it all, {class}. Burn it to cinders!", completion = "Good! Without heavy equipment, the Horde will have to pull back to regroup. We've bought ourselves some time to re-secure the fortress. Well done!", objectives = "Use Paxton's Torch to burn 3 Rageroar Catapults and 1 Rageroar Blade Thrower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24949] = { id = 24949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Duty", description = "Let's not be wasteful here, babe. These pirates have tons of valuable nonsense just sitting around, waiting to be fenced. Can you believe they just sit on this stuff?\n\nI mean, why do they even bother taking it if it's just going to sit around? Stolen goods should be sold off and used to buy shiny new things.\n\nAnyway, be a dear and go grab as much of their loot as you can carry while you're out busting heads. Ciao!", progress = "Let's see what you've got. You're not hiding any for yourself, are you? You'll never find a buyer without me, you know.", completion = "Beautiful! And to think these idiots were just sitting on it.\n\nHere's a bit up front, we'll talk about profit-sharing bonuses later.", objectives = "Collect 10 pieces of Pirate Booty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24950] = { id = 24950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Dreadbeard", description = "Alright, babe, I've got something bigger for you to take on here.\n\nWe spotted the captain of the Southsea over on one of his boats to the south; that's to the south, and NOT the one we've been suicidally bum-rushing for the better part of several hours. He's sitting up there, smug and stoic, watching us war down here.\n\nI'll spare you the \"hostile takeover\" jokes. Get on his ship and beat the tar out of him, and we're done here!", progress = "I'm flattered that you'd rather stay here and flirt with me than go kill that pirate captain. So flattered that I might not fire you if you get going right now and do it already.", completion = "Sea giants? You think he was training them towards Gadgetzan on purpose?\n\nWhatever, he's splitsville now. And Gadgetzan owes us big time! I can't wait to see the look on Marin's face.\n\nHere's your cut, babe. You're moving up in the world.", objectives = "Kill Captain Dreadbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24951] = { id = 24951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Idea", description = "Now that we've got a good pile of fresh chunks, we just tie it to this rope...and now you're ready to go catch me a silithid.\n\nWhat? Don't give me that look, it's perfectly safe. Well, mostly safe. Okay, you might die painfully. But it'll be easy! Just throw this meat out there, wait for a bug to pounce on it, and then drag 'em back here by the rope!\n\nGo after one of the swarmers. I haven't seen the other ones go for hyenas before, and you should find plenty of swarmers around the edge of the pit.", progress = "I don't see any bug with you, pal.", completion = "Look at the size of it! It's glorious. This ugly sucker's gonna help us bring down the whole hive.", objectives = "Use the Bootlegger Bug Bait to capture a Hazzali Swarmer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24952] = { id = 24952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Boot Boost", description = "You need to get those boots down into the caldera to Hobart Grapplehammer.\n\nNow that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot.\n\nWhen you're ready, activate the boots. Don't worry, they're automatically set to land you safely.\n\nI think.", progress = "Well there you are!", completion = "There's no time to waste, boy!\n\nWhat's wrong with the actuator on the left boot?!", objectives = "Use the Rockin' Powder Infused Rocket Boots and deliver them to Hobart Grapplehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24953] = { id = 24953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Trying to Kill Some Bugs", description = "Now it's time for my plan to go into full effect. We've got the captured bug strapped up with as many explosives as it can carry, and with Soothfancy's mostly amazing mental powers, we're gonna drive that sucker straight down into the center of the underground hive.\n\nAnd then...BOOM! No more bugs!\n\nYou get the personal honor of directin' the ugly thing. Go talk to Narain and get set up with your bug-pal.", progress = "I didn't hear no cave-ins, pal! Try again!", completion = "Oh man, that was awesome! You should've seen the flames coming out of the hive!\n\nHere's your reward, for entertaining me as much as for clearing the hive!", objectives = "Talk to Narain Soothfancy to pilot the Mind-Controlled Swarmer into the Gaping Chasm hive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24954] = { id = 24954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of a Turtle God", description = "Volcanoth is the turtle god in the cave that these primitives worship.\n\nIt's not really a god.\n\n<Hobart rolls his eyes.>\n\nBut it is tough enough that I'm going to have to devise a new weapon for you from the one functioning boot we have left.\n\nI think that the age-old motto of \"fight fire with fire\" applies here. Plus, I like fire!\n\nLet's get some fire glands from Volcanoth's children. That should give me time to modify the rocket boot into something more fitting.", progress = "No time like the present to be done with the simple task I put before you, {name}. Wouldn't you agree?", completion = "Careful with those glands, {name}, careful!\n\n\n\nAnd now to load them into the refashioned shredder boot. I'm certain that you'll be surprised and amazed by my genius invention.", objectives = "Collect 5 Fire Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24955] = { id = 24955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Chartered", description = "As I may have mentioned, I'm trying to get these Dunemaul ogres to join the Horde..and  work for the Bilgewater Cartel as cheap local labor.\n\nTo pull this off, we've gotta pay lip service to the actual initiation process and all that, or I'm going to catch flak later on. So I've gotten this charter drawn up, and slapped the initiation rites onto our own limited time offer labor stipulation contract.\n\nI've got a disguise for you here, so suit up and get all these signatures filled out.", progress = "Babe, there's still blank spots on this sheet. Being near ogres isn't rubbing off on your intelligence, I hope.", completion = "Wow, nice work! I'm amazed you even got them to hold a pen without eating it.\n\nYou can uh, just throw the suit over there. Away from me. In the fire.", objectives = "Obtain 10 Charter Signatures from Dunemaul Ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24956] = { id = 24956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silencing Rageroar", description = "I have encountered the Rageroar clan before, {name}. They are led not by an orc, but by a monster - a war-gorged fiend without a shred of decency or compassion. He and his lieutenants must be killed, not just to save Northwatch, but for the good of all of Azeroth.\n\nKarga Rageroar wears a helm. Execute him, {class}, and bring the helm to me. It is of ... particular importance.\n\nRageroar has made his camp across the chasm, east of here.", progress = "Is he dead? Do you have his ... helm?", completion = "<Tolliver grasps the helmet reverently with quivering hands.>\n\nRageroar's battleships intercepted our vessel as we fled from Gilneas. We were to be carried here as trophies to the Warchief. As we neared the shore, some of us fought back. Rageroar - he began killing indiscriminately - howling with laughter. Our ship capsized and he ordered his men to fire at us as we drowned. Few of us made it to land.\n\nAfterwards, I learned that he wore my brother's scalp as... as a trophy.\n\n<He closes his eyes.>", objectives = "Slay 4 Rageroar Lieutenants and acquire Rageroar's Helm by killing Karga Rageroar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24957] = { id = 24957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get The Centipaarty Started", description = "Okay, babe. Like I said, the ogres are too dumb to know what signing that charter meant. Now we have to actually get them to come along with us, so we'll be procuring what is apparently beloved local flavor.\n\nBeloved local flavor for drooling idiots, I mean.\n\nJust pop on over to the Noxious Lair to the west, it's that big horrible pit full of dangerous silithid. Kill a bunch of the Centipaar silithid and bring back the pieces so we can hand 'em out, okay? Ciao.", progress = "Have you got enough? These ogres don't look like the type to like small portions.", completion = "Ugh! This entire camp is like a sampler course of awful smells.\n\nLet's not handle these things any longer than we have to.", objectives = "Collect 20 Centipaarts from Centipaar Silithid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24958] = { id = 24958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanoth!", description = "It took a lot of blood, sweat, and tears, but the Bootzooka, patent-pending, is ready for use!\n\nThese no-good pygmies have been feeding our people to their \"god\", Volcanoth, and they're about to unleash it on our town!\n\nYou have to get into the cave and kill that thing before it's too late!", completion = "I managed to get everyone else safely back to town.\n\nJump in, we gotta get out of here before the volcano blows for good!!!", objectives = "Use the Bootzooka to slay Volcanoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24959] = { id = 24959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh out of the Grave", description = "{name}!\n\nRise, {name}!\n\nWelcome back to the realm of the living.  With the blessing and power of the Dark Lady, I have freed you from death's grip.\n\nYou are no slave, {name}.  You are free to follow whatever path you choose from here.  If you choose to serve the Dark Lady Sylvanas, I recommend you speak with Undertaker Mordo.  You will find him behind me, in the graveyard.", completion = "Hello there.  You must be... {name}?", objectives = "Report to Undertaker Mordo at the Deathknell Graves in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24960] = { id = 24960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wakening", description = "King, peasant, or {class}... I don't care WHAT you were before.  I just need somebody with a working tongue.\n\nBeing raised from the dead is strenuous.  Not everyone copes with it as well as you did.  In particular, there are three newly-raised undead who are having trouble coping right now.\n\nI want you to find them and talk to them.  It might be that they just need someone that they can relate with.\n\nYou'll find them here in the graveyard.", progress = "No dilly-dallying now.  You're among the Forsaken now, and we hold ours to a higher standard.", completion = "You've done well, {class}.  As you can see, not all of us have resigned to our fates.  I'm glad to see that you're at least willing to work.\n\nValdred will be a valuable asset to the Forsaken.  As for the other two... there is not much we can do.  We cannot force them to join us.", objectives = "Speak with Marshal Redpath, Lilian Voss, and Valdred Moray.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
